/**
 * ZeroTouchSection
 *
 * Three-column animated feature grid for the Sequences page.
 * Same chrome as EnrichmentSection (dot-grid, dashed rules, hatching),
 * but each card area contains a custom animation instead of a static image.
 *
 * Panel 1 – Signal-based enrollment: animated blue glow + pulsing connector
 * Panel 2 – One sequence, any sender: rotating dashed circles + provider badges
 * Panel 3 – Automate scheduled sending: infinite-scroll contact list
 */

"use client"

import { motion } from "framer-motion"

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ZeroTouchSectionProps {
  heading: string
  subheading: string
}

